/** Plugin-local language override; following DSH delegates to its translator. */
export function codekinTranslator(host, language = 'auto') {
    if (language === 'auto')
        return host;
    const dictionary = language === 'zh' ? zh : en;
    return (key, params) => Object.hasOwn(dictionary, key)
        ? dictionary[key].replace(/\{(\w+)\}/g, (token, name) => params !== undefined && Object.hasOwn(params, name) ? String(params[name]) : token)
        : host(key, params);
}
